<template><div class="main-content"><breadcumb :page="viewing?(invoice?invoice.supplier_invoice_number:'Supplier Invoice'):'Record Supplier Invoice'" folder="Procurement"/>
<b-card v-if="viewing&&invoice"><div class="mb-3"><b-button v-if="invoice.status==='draft'&&can('supplier_invoices_post')" variant="outline-success" @click="record">Record invoice</b-button><b-button v-if="invoice.status==='recorded'&&can('purchases_from_supplier_invoice')&&can('purchases_post')" variant="primary" class="ml-2" @click="postPurchase">Create and post Purchase</b-button><a v-if="invoice.attachment_path" class="btn btn-outline-secondary ml-2" :href="api+'procurement/supplier-invoices/'+invoice.id+'/attachment'">Attachment</a></div><b-row><b-col md="6"><p><strong>Supplier:</strong> {{invoice.provider.name}}</p><p><strong>PO:</strong> <router-link v-if="invoice.purchase_order" :to="'/app/procurement/purchase-orders/'+invoice.purchase_order_id">{{invoice.purchase_order.number}}</router-link><span v-else> Direct receipt</span></p><p><strong>Gate Pass:</strong> <router-link :to="'/app/procurement/gate-passes/'+invoice.gate_pass_id">{{invoice.gate_pass.number}}</router-link></p></b-col><b-col md="6"><p><strong>Tax type:</strong> {{label(invoice.tax_type)}}</p><p><strong>Total:</strong> {{invoice.grand_total}}</p><p><strong>Status:</strong> {{label(invoice.status)}}</p><p v-if="invoice.purchase"><strong>Purchase:</strong> <router-link :to="'/app/purchases/detail/'+invoice.purchase.id">{{invoice.purchase.Ref}}</router-link></p></b-col></b-row><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>Qty</th><th>Cost</th><th>Tax</th><th>Total</th></tr></thead><tbody><tr v-for="i in invoice.items" :key="i.id"><td>{{i.product_name}} {{i.variant_name||''}}</td><td>{{i.quantity}}</td><td>{{i.unit_cost}}</td><td>{{i.tax_amount}}</td><td>{{i.line_total}}</td></tr></tbody></table></div></b-card>
<b-card v-else-if="meta"><b-form @submit.prevent="save"><b-row><b-col md="3"><b-form-group label="Supplier invoice number *"><b-form-input v-model="form.supplier_invoice_number" required/></b-form-group></b-col><b-col md="3"><b-form-group label="Invoice date *"><b-form-input type="date" v-model="form.invoice_date" required/></b-form-group></b-col><b-col md="3"><b-form-group label="Due date"><b-form-input type="date" v-model="form.due_date"/></b-form-group></b-col><b-col md="3"><b-form-group label="Invoice tax type"><b-form-select v-model="form.tax_type" :options="[{value:'gst',text:'GST Invoice'},{value:'non_gst',text:'Non-GST Invoice'}]"/></b-form-group></b-col><b-col md="6"><b-form-group label="Invoice attachment"><b-form-file @input="file=$event" accept="image/jpeg,image/png,application/pdf"/></b-form-group></b-col></b-row><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>Accepted</th><th>Previously invoiced</th><th>Remaining</th><th>Invoice qty</th><th>Unit cost</th><th v-if="form.tax_type==='gst'">Tax</th></tr></thead><tbody><tr v-for="l in lines" :key="l.gate_pass_item_id"><td>{{l.product}} {{l.model||''}}</td><td>{{l.accepted_quantity}}</td><td>{{l.previously_invoiced}}</td><td>{{l.remaining_quantity}}</td><td><b-form-input type="number" step="0.000001" min="0" :max="l.remaining_quantity" v-model.number="l.quantity"/></td><td><b-form-input type="number" step="0.01" min="0" v-model.number="l.unit_cost"/></td><td v-if="form.tax_type==='gst'"><v-select v-model="l.tax_id" :reduce="x=>x.id" label="name" :options="meta.taxes"/></td></tr></tbody></table></div><b-row><b-col md="3"><b-form-group label="Other charges"><b-form-input type="number" min="0" step="0.01" v-model.number="form.other_charges"/></b-form-group></b-col><b-col md="3"><b-form-group label="Freight"><b-form-input type="number" min="0" step="0.01" v-model.number="form.freight_charges"/></b-form-group></b-col><b-col md="6"><b-form-group label="Notes"><b-form-textarea v-model="form.notes"/></b-form-group></b-col></b-row><b-button type="submit" variant="primary">Record supplier invoice</b-button></b-form></b-card></div></template>
<script>import{mapGetters}from'vuex';export default{data:()=>({invoice:null,meta:null,lines:[],file:null,api:'/api/',form:{supplier_invoice_number:'',invoice_date:new Date().toISOString().slice(0,10),due_date:null,tax_type:'non_gst',other_charges:0,freight_charges:0,notes:''}}),computed:{...mapGetters(['currentUserPermissions']),viewing(){return this.$route.name==='procurement_invoice_detail'}},mounted(){this.viewing?this.loadInvoice():this.loadMeta()},methods:{can(p){return(this.currentUserPermissions||[]).includes(p)},label(v){return String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())},loadInvoice(){axios.get('procurement/supplier-invoices/'+this.$route.params.id).then(r=>this.invoice=r.data.supplier_invoice)},loadMeta(){axios.get('procurement/gate-passes/'+this.$route.params.id+'/invoice-metadata').then(r=>{this.meta=r.data;this.form.tax_type=r.data.default_tax_type;this.lines=r.data.items.map(x=>({...x,quantity:0,unit_cost:x.default_cost,discount:0,discount_method:'fixed',tax_id:r.data.taxes[0]?.id||null}))})},save(){let fd=new FormData();Object.entries({...this.form,gate_pass_id:this.$route.params.id}).forEach(([k,v])=>v!==null&&fd.append(k,v));fd.append('items',JSON.stringify(this.lines.filter(x=>Number(x.quantity)>0)));if(this.file)fd.append('attachment',this.file);axios.post('procurement/supplier-invoices',fd).then(r=>this.$router.push('/app/procurement/supplier-invoices/'+r.data.supplier_invoice.id))},record(){axios.post('procurement/supplier-invoices/'+this.invoice.id+'/record').then(this.loadInvoice)},postPurchase(){axios.post('procurement/supplier-invoices/'+this.invoice.id+'/create-purchase').then(this.loadInvoice).catch(e=>this.$bvToast.toast(e.response?.data?.message||'Posting failed',{variant:'danger'}))}}}</script>
